contract = {"trajectory": {"shape": (1, 20, 2), "dtype": "float32", "unit": "m", "frame": "ego", "hz": 10}}
model_out = {"trajectory": {"shape": (1, 16, 2), "dtype": "float16", "unit": "m", "frame": "ego", "hz": 8}}
for name, want in contract.items():
    got = model_out[name]
    for k, v in want.items():
        if got.get(k) != v:
            print(f"{name}.{k}: 기대 {v} / 실제 {got.get(k)}")
# trajectory.shape: 기대 (1, 20, 2) / 실제 (1, 16, 2)
# trajectory.dtype: 기대 float32 / 실제 float16
# trajectory.hz: 기대 10 / 실제 8
